#!/usr/bin/env node
/**
 * Dynamic meta for the whole site, generated by scripts/dynamic-meta.js:
 *   research/meta/page-records.json   Muse's 67 records (used as given)
 *   src/data/page-records.js          records for the rest of the site
 * Records from page-records.js may list several trust signals; the first one
 * the generator returns with zero flags is kept. Key questions must be unique
 * across both sets. Output: research/meta/meta-output.csv, read by the build.
 * Exit 1 if anything is flagged.
 */
const fs = require('fs');
const path = require('path');
const { generateMeta } = require('./dynamic-meta.js');
const site = require('../src/data/page-records.js');

const ROOT = path.join(__dirname, '..');
const MUSE = path.join(ROOT, 'research', 'meta', 'page-records.json');
const OUT = path.join(ROOT, 'research', 'meta', 'meta-output.csv');

function run() {
  const muse = JSON.parse(fs.readFileSync(MUSE, 'utf8')).map((r) => ({ r, trusts: [r.trust_signal] }));
  const mine = site.records.map((r) => ({ r, trusts: site.TRUSTS }));
  const seen = new Map();
  const out = [];
  for (const { r, trusts } of [...muse, ...mine]) {
    let best = null;
    for (const t of trusts) {
      const m = generateMeta({ ...r, trust_signal: t });
      if (!best || m.flags.length < best.flags.length) best = m;
      if (!m.flags.length) break;
    }
    const k = r.key_question.trim().toLowerCase();
    if (seen.has(k)) best.flags.push(`DUPLICATE KEY QUESTION (${seen.get(k)})`);
    seen.set(k, r.slug);
    out.push({ r, ...best });
  }
  const cell = (v) => (v == null ? '' : /[",\n]/.test(String(v)) ? `"${String(v).replace(/"/g, '""')}"` : String(v));
  const rows = [['Page', 'Slug', 'Page Type', 'Key Question', 'Title', 'Title Chars', 'Description', 'Description Chars', 'Flags']];
  for (const o of out)
    rows.push([o.r.page, o.r.slug, o.r.page_type, o.r.key_question, o.title, o.title ? o.title.length : '', o.description, o.description ? o.description.length : '', o.flags.join('; ')]);
  fs.writeFileSync(OUT, rows.map((row) => row.map(cell).join(',')).join('\n') + '\n');
  return { count: out.length, flagged: out.filter((o) => o.flags.length) };
}

if (require.main === module) {
  const { count, flagged } = run();
  console.log(`records: ${count}, flagged: ${flagged.length}, output: research/meta/meta-output.csv`);
  flagged.forEach((o) => console.log(`  ${o.r.slug}: ${o.flags.join('; ')} | ${o.title} | ${o.description}`));
  if (flagged.length) process.exitCode = 1;
}
module.exports = { run };
